-- ICARE Kola Branch Live Demo Seed (Phase 18 Bank-Centric Aligned)
-- Auto-generated from scripts/maintenance/setup_kola_demo.py
-- Scope: Kola Branch ONLY (dd09c735-3b1e-4eeb-89a8-d27a85e02156).
-- Ogijo and all other branches remain 100% untouched.
-- =============================================================================

BEGIN;

-- 1. Clean up prior Kola-only data in strict FK child -> parent order
DO $$
DECLARE
    v_kola_branch UUID := 'dd09c735-3b1e-4eeb-89a8-d27a85e02156'::uuid;
    v_bm UUID := '7bf1899f-3a6d-54df-b505-a8274aac7369'::uuid;
    v_co1 UUID := 'fd5d64ba-73d2-51e8-a7d7-560b4f01fb09'::uuid;
    v_ft_event_ids UUID[];
    v_loan_ids UUID[];
    v_client_ids UUID[];
    v_group_ids UUID[];
    v_repay_ids UUID[];
    v_guarantor_ids UUID[];
BEGIN
    SELECT COALESCE(array_agg(DISTINCT event_id), ARRAY[]::uuid[]) INTO v_ft_event_ids
      FROM public.financial_transactions WHERE branch_id = v_kola_branch AND event_id IS NOT NULL;
    SELECT COALESCE(array_agg(loan_id), ARRAY[]::uuid[]) INTO v_loan_ids
      FROM public.loans WHERE branch_id = v_kola_branch;
    SELECT COALESCE(array_agg(client_id), ARRAY[]::uuid[]) INTO v_client_ids
      FROM public.clients WHERE branch_id = v_kola_branch;
    SELECT COALESCE(array_agg(group_id), ARRAY[]::uuid[]) INTO v_group_ids
      FROM public.groups WHERE branch_id = v_kola_branch;
    SELECT COALESCE(array_agg(id), ARRAY[]::uuid[]) INTO v_repay_ids
      FROM public.repayments WHERE branch_id = v_kola_branch OR loan_id = ANY(v_loan_ids);
    SELECT COALESCE(array_agg(DISTINCT guarantor_id), ARRAY[]::uuid[]) INTO v_guarantor_ids
      FROM public.loan_guarantors WHERE loan_id = ANY(v_loan_ids);

    DELETE FROM public.area_eod_confirmations WHERE branch_id = v_kola_branch;
    DELETE FROM public.master_cashbook WHERE branch_id = v_kola_branch;
    DELETE FROM public.co_cashbooks WHERE branch_id = v_kola_branch;
    DELETE FROM public.financial_ledger_entries WHERE branch_id = v_kola_branch;
    UPDATE public.financial_transactions SET reversal_of = NULL
      WHERE branch_id = v_kola_branch AND reversal_of IS NOT NULL;
    DELETE FROM public.financial_transactions WHERE branch_id = v_kola_branch;
    DELETE FROM public.event_processing WHERE event_id = ANY(v_ft_event_ids);
    DELETE FROM public.event_store
      WHERE event_id = ANY(v_ft_event_ids)
         OR aggregate_id = v_kola_branch
         OR aggregate_id = ANY(v_loan_ids)
         OR aggregate_id = ANY(v_client_ids)
         OR aggregate_id = ANY(v_group_ids);
    DELETE FROM public.collection_performance WHERE loan_id = ANY(v_loan_ids) OR client_id = ANY(v_client_ids);
    DELETE FROM public.loan_payoff_excess_records WHERE branch_id = v_kola_branch OR loan_id = ANY(v_loan_ids) OR repayment_id = ANY(v_repay_ids);
    DELETE FROM public.loan_overdue_recovery_records WHERE branch_id = v_kola_branch OR loan_id = ANY(v_loan_ids) OR repayment_id = ANY(v_repay_ids);
    DELETE FROM public.repayments WHERE id = ANY(v_repay_ids);
    DELETE FROM public.loan_schedule WHERE loan_id = ANY(v_loan_ids);
    DELETE FROM public.loan_guarantors WHERE loan_id = ANY(v_loan_ids);
    DELETE FROM public.asset_stock_movements WHERE branch_id = v_kola_branch OR loan_id = ANY(v_loan_ids);
    DELETE FROM public.withdrawal_requests WHERE branch_id = v_kola_branch;
    DELETE FROM public.fees WHERE branch_id = v_kola_branch;
    DELETE FROM public.individual_savings WHERE branch_id = v_kola_branch;
    DELETE FROM public.group_savings WHERE branch_id = v_kola_branch;
    DELETE FROM public.internal_savings WHERE branch_id = v_kola_branch;
    DELETE FROM public.laps_savings WHERE branch_id = v_kola_branch;
    DELETE FROM public.treasury_transactions WHERE branch_id = v_kola_branch;
    DELETE FROM public.client_status_history WHERE client_id = ANY(v_client_ids);
    DELETE FROM public.client_memberships WHERE branch_id = v_kola_branch OR client_id = ANY(v_client_ids);
    DELETE FROM public.client_profile_update_requests WHERE branch_id = v_kola_branch OR client_id = ANY(v_client_ids);
    DELETE FROM public.client_transfers WHERE from_branch_id = v_kola_branch OR to_branch_id = v_kola_branch OR client_id = ANY(v_client_ids);
    DELETE FROM public.loans WHERE loan_id = ANY(v_loan_ids);
    DELETE FROM public.guarantors g WHERE g.guarantor_id = ANY(v_guarantor_ids)
      AND NOT EXISTS (SELECT 1 FROM public.loan_guarantors lg WHERE lg.guarantor_id = g.guarantor_id);
    DELETE FROM public.clients WHERE client_id = ANY(v_client_ids);
    DELETE FROM public.groups WHERE group_id = ANY(v_group_ids);
    DELETE FROM public.audit_logs WHERE user_id IN (v_bm, v_co1);
    DELETE FROM public.user_audit_logs WHERE branch = 'Kola' OR user_id IN (v_bm, v_co1);
    DELETE FROM public.idempotency_keys WHERE branch_id = v_kola_branch::text;
    DELETE FROM public.branch_closures WHERE branch_id = v_kola_branch;
END $$;

-- 2. Branch Metadata (Kola)
ON CONFLICT (branch_id) DO UPDATE SET name = EXCLUDED.name, code = EXCLUDED.code, cashbook_defaults = EXCLUDED.cashbook_defaults, officer_assignments = EXCLUDED.officer_assignments, updated_at = EXCLUDED.updated_at;

-- 3. Kola Staff & Role Assignments
ON CONFLICT (username) DO UPDATE SET password_hash = EXCLUDED.password_hash, full_name = EXCLUDED.full_name, branch_id = EXCLUDED.branch_id, extra_fields = EXCLUDED.extra_fields, is_active = EXCLUDED.is_active;
ON CONFLICT (username) DO NOTHING;
ON CONFLICT (user_id, role_id) DO NOTHING;
ON CONFLICT (am_id, branch_id) DO NOTHING;

